files.rules.yaml:
constraint_set_id: parity.values
bindings:
  input:
    key_fields: [loan_id, seq]
rules:
  - {id: UNIQUE_OWNER, severity: error, binding: input, op: unique, columns: [owner, balance]}
  - {id: OWNER_PRESENT, severity: warn, binding: input, op: not_null, columns: [owner, flag]}
  - {id: BIG_BALANCE, severity: error, binding: input, op: predicate, expr: {gt: [{column: balance}, 1000]}}
  - {id: OWNER_NAMED, severity: error, binding: input, op: predicate, expr: {eq: [{column: owner}, "nobody"]}}
  - {id: FLAG_SET, severity: error, binding: input, op: predicate, expr: {eq: [{column: flag}, false]}}
  - {id: ROWS, severity: error, binding: input, op: row_count, compare: {eq: 2}}
  - {id: SUM, severity: error, binding: input, op: aggregate_compare, aggregate: {sum: seq}, compare: {lt: 1}}
  - {id: MAX, severity: error, binding: input, op: aggregate_compare, aggregate: {max: balance}, compare: {lt: 1}}

